"""Shell resolver ownership, unavailable interfaces and implicit identities."""

import ctypes
import sys
from contextlib import contextmanager
from pathlib import Path, PureWindowsPath

import pytest

from docking.platform.backends.windows import appresolver


@pytest.mark.parametrize(
    "failure,identity,expected",
    [
        (
            None,
            "Microsoft.AutoGenerated.{fixture}",
            "Microsoft.AutoGenerated.{fixture}",
        ),
        ("resolver", "Native.App", None),
        ("item", "Native.App", None),
        ("resolve", "Native.App", None),
        ("null", "Native.App", None),
        (None, "", None),
        (None, "invalid identity", None),
        (None, "a" * 129, None),
    ],
)
def test_native_resolver_frees_partial_results_and_com_interfaces(
    tmp_path, monkeypatch, failure, identity, expected
):
    released, freed, calls = [], [], []
    buffer = ctypes.create_unicode_buffer(identity)

    @contextmanager
    def apartment():
        yield object()

    def assign(output, value):
        ctypes.cast(output, ctypes.POINTER(ctypes.c_void_p))[0] = value

    def bind(_library, name, *_signature):
        def invoke(*args):
            calls.append(name)
            if name == "CoTaskMemFree":
                freed.append(args[0].value)
                return None
            if name == "CoCreateInstance":
                assign(args[-1], 11)
                return -1 if failure == "resolver" else 0
            assert name == "SHCreateItemFromParsingName"
            assert args[0] == str(
                PureWindowsPath(tmp_path / "résumé 日本語.lnk")
            ).replace("/", "\\")
            assign(args[-1], 22)
            return -1 if failure == "item" else 0

        return invoke

    def method(pointer, index, *_signature):
        assert pointer.value == 11 and index == 3

        def invoke(_this, item, output):
            assert item.value == 22
            if failure != "null":
                assign(output, ctypes.addressof(buffer))
            return -1 if failure == "resolve" else 0

        return invoke

    monkeypatch.setattr(appresolver, "apartment", apartment)
    monkeypatch.setattr(appresolver, "bind", bind)
    monkeypatch.setattr(appresolver, "method", method)
    monkeypatch.setattr(appresolver, "release", lambda p: released.append(p.value))
    monkeypatch.setattr(ctypes, "WinDLL", lambda *_a, **_kw: object(), raising=False)
    result = appresolver.shortcut_application_id(tmp_path / "résumé 日本語.lnk")
    assert result == expected
    assert released == ([11] if failure == "resolver" else [22, 11])
    allocated = failure not in {"resolver", "item", "null"}
    assert freed == ([ctypes.addressof(buffer)] if allocated else [])


@pytest.mark.skipif(sys.platform != "win32", reason="Native Windows shell resolver")
def test_native_resolver_accepts_forward_slashes_from_an_msys2_shell(tmp_path):
    from docking.platform.backends.windows.shortcuts import write_shortcut

    path = tmp_path / "résumé 日本語.lnk"
    write_shortcut(path, executable=Path(sys.executable), name="résumé 日本語")
    identifier = appresolver.shortcut_application_id(path)
    assert identifier
    for spelling in (str(path).replace("\\", "/"), str(PureWindowsPath(path))):
        assert appresolver.shortcut_application_id(Path(spelling)) == identifier
